// Muokkaa näitä tietoja seuraavaa leiriä varten.
// optional: true -> tavara on valinnainen, ei lasketa pakolliseen edistymispalkkiin.
const CAMP = { storageKey: "vsnk-pakkaus-syysleiri-2026-v2" };

const CATEGORIES = [
  { id:"nukkuminen", label:"Nukkumiseen", color:"var(--accent-moss)", items:[
    {label:"Makuupussi", icon:"🛏️"}, {label:"Aluslakana", icon:"🛏️"}, {label:"Tyynyliina", icon:"🛌"}
  ]},
  { id:"vaatteet", label:"Vaatteet", color:"var(--accent-rust)", items:[
    {label:"Mukavat olovaatteet", icon:"👕"}, {label:"Yöpuku", icon:"🌙"},
    {label:"Reilusti vaihtovaatteita", icon:"👖"}, {label:"Lämmintä välivaatetta", icon:"🧥"},
    {label:"Säänkestävä ulkoilutakki ja -housut", icon:"🌧️"}, {label:"Pipo ja hanskat", icon:"🧤"},
    {label:"Kumisaappaat", icon:"👢"}, {label:"Lenkkarit", icon:"👟"}
  ]},
  { id:"peseytyminen", label:"Peseytymiseen", color:"var(--accent-teal)", items:[
    {label:"Pesuaineet", icon:"🧼"}, {label:"Nimikoitu pussi, jossa hammasharja ja -muki", icon:"🪥"},
    {label:"Pyyhe", icon:"🛁"}, {label:"Uimapuku", icon:"🩱"}
  ]},
  { id:"retkeen", label:"Retkivarusteet", color:"var(--accent-mustard)", items:[
    {label:"Taskulamppu tai otsalamppu", icon:"🔦"}, {label:"Nimikoitu vesipullo", icon:"🧴"}
  ]},
  { id:"tarkeaa", label:"Muista erikseen", color:"var(--accent-plum)", items:[
    {label:"Lääkkeet nimikoidussa pussissa ohjeineen", icon:"💊", optional:true},
    {label:"Puhelin nimellä, hälytykset ja herätykset pois", icon:"📱", optional:true},
    {label:"Unilelu", icon:"🧸", optional:true}
  ]},
  { id:"herkut", label:"Herkkupussi", color:"var(--accent-amber)", items:[
    {label:"Yksi noin 250 g makeispussi", icon:"🍬", optional:true},
    {label:"Yksi pussi muita naposteltavia", icon:"🍿", optional:true},
    {label:"Juomaa yhteensä enintään 1 litra", icon:"🥤", optional:true}
  ]}
];

let state = {};
try{
  const saved = localStorage.getItem(CAMP.storageKey);
  state = saved ? JSON.parse(saved) : {};
}catch(e){ state = {}; }

function itemKey(catId, idx){ return catId + ":" + idx; }
function saveState(){ try{ localStorage.setItem(CAMP.storageKey, JSON.stringify(state)); }catch(e){} }

function totalCounts(){
  let total=0, done=0, optTotal=0, optDone=0;
  CATEGORIES.forEach(cat=>{
    cat.items.forEach((item, idx)=>{
      const checked = !!state[itemKey(cat.id, idx)];
      if(item.optional){ optTotal++; if(checked) optDone++; }
      else { total++; if(checked) done++; }
    });
  });
  return {total, done, optTotal, optDone};
}

function renderChecklist(){
  const col = document.getElementById("checklistCol");
  col.innerHTML = "";
  CATEGORIES.forEach(cat=>{
    const box = document.createElement("div");
    box.className = "category";

    const head = document.createElement("div");
    head.className = "category-head";
    const dot = document.createElement("span");
    dot.className = "tag-dot";
    dot.style.background = cat.color;
    head.appendChild(dot);
    const title = document.createElement("span");
    title.textContent = cat.label;
    head.appendChild(title);
    const count = document.createElement("span");
    count.className = "count";
    head.appendChild(count);
    box.appendChild(head);

    const ul = document.createElement("ul");
    ul.className = "item-list";

    cat.items.forEach((item, idx)=>{
      const key = itemKey(cat.id, idx);
      const li = document.createElement("li");
      if(state[key]) li.classList.add("checked");

      const chk = document.createElement("span");
      chk.className = "box";

      const iconSpan = document.createElement("span");
      iconSpan.className = "icon";
      iconSpan.textContent = item.icon || "🎒";

      const wrap = document.createElement("span");
      wrap.className = "label-wrap";
      const lab = document.createElement("span");
      lab.className = "label";
      lab.textContent = item.label;
      wrap.appendChild(lab);
      if(item.optional){
        const badge = document.createElement("span");
        badge.className = "opt-badge";
        badge.textContent = "valinnainen";
        wrap.appendChild(badge);
      }

      li.appendChild(chk);
      li.appendChild(iconSpan);
      li.appendChild(wrap);

      li.addEventListener("click", ()=>{
        const nowChecked = !state[key];
        state[key] = nowChecked;
        li.classList.toggle("checked");
        saveState();
        renderProgress();
        document.getElementById("celebrateBox").classList.remove("show");
        document.getElementById("readyFeedback").textContent = "";
        if(nowChecked){
          packAnimation(item.icon || "🎒");
          li.classList.remove("pop");
          void li.offsetWidth;
          li.classList.add("pop");
          setTimeout(()=>li.classList.remove("pop"), 420);
          playItemSound(item.label);
        }
      });
      ul.appendChild(li);
    });

    box.appendChild(ul);
    col.appendChild(box);

    const checkedInCat = cat.items.filter((_,idx)=>state[itemKey(cat.id, idx)]).length;
    count.textContent = checkedInCat + " / " + cat.items.length;
  });
}

function renderProgress(){
  const {total, done, optTotal, optDone} = totalCounts();
  const pct = total ? Math.round((done/total)*100) : 0;
  document.getElementById("progressFill").style.width = pct + "%";
  document.getElementById("progressText").textContent = done + " / " + total + " pakattu";
  const optNote = document.getElementById("optionalNote");
  optNote.textContent = optTotal
    ? "Näiden lisäksi valinnaisia tavaroita pakattu " + optDone + " / " + optTotal + " (esim. herkut, lääkkeet, puhelin, unilelu)."
    : "";

  const readyBtn = document.getElementById("readyBtn");
  const feedback = document.getElementById("readyFeedback");
  const ready = total > 0 && done === total;
  readyBtn.disabled = !ready;
  if(!ready){
    const missing = total - done;
    feedback.textContent = missing > 0
      ? "Vielä puuttuu " + missing + " pakollista tavaraa."
      : "";
  }
}

function checkReady(){
  const box = document.getElementById("celebrateBox");
  const feedback = document.getElementById("readyFeedback");
  box.classList.add("show");
  feedback.textContent = "";
  dropLeaves();
  playAudioClip("yay");
}

function playCheerSound(){
  try{
    if(!sharedAudioCtx){
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if(!Ctx) return;
      sharedAudioCtx = new Ctx();
    }
    const ctx = sharedAudioCtx;
    if(ctx.state === "suspended") ctx.resume();
    const now = ctx.currentTime;
    // Pieni riemukas "jeee"-fanfaari: nouseva kolmisointu
    const notes = [523.25, 659.25, 784.0, 1046.5]; // C5 E5 G5 C6
    notes.forEach((freq, idx)=>{
      const start = now + idx * 0.09;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "triangle";
      osc.frequency.setValueAtTime(freq, start);
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(0.25, start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.32);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(start);
      osc.stop(start + 0.35);
    });
  }catch(e){ /* äänet eivät ole pakollisia toiminnalle */ }
}

// Matkalaukun valokuvat: kahdeksan kehystä auki-tilasta kiinni-tilaan.
// Alkuperäinen materiaali käyttäjän omasta Canva-kuvapankista.
const FRAMES = [
"data:image/png;base64,",
"data:image/png;base64,",
"data:image/png;base64,",
"data:image/png;base64,",
"data:image/png;base64,",
"data:image/png;base64,",
"data:image/png;base64,",
"data:image/png;base64,"
];
const LAST_FRAME = FRAMES.length - 1;

function setFrame(i){
  const src = FRAMES[i];
  const big = document.getElementById("suitcaseImgBig");
  if(big) big.src = src;
}
setFrame(0);
// Etenemispalkin pieni matkalaukku on kiinteä kuva, ei animoitu
const staticImg = document.getElementById("suitcaseImgStatic");
if(staticImg) staticImg.src = FRAMES[0];

let frameTimer = null;
function playFrames(sequence, stepMs, onDone, onStep){
  if(frameTimer) clearInterval(frameTimer);
  let i = 0;
  frameTimer = setInterval(()=>{
    setFrame(sequence[i]);
    if(onStep) onStep(i);
    i++;
    if(i >= sequence.length){
      clearInterval(frameTimer);
      frameTimer = null;
      if(onDone) onDone();
    }
  }, stepMs);
}

let packTimer1 = null;
let sharedAudioCtx = null;
function getAudioCtx(){
  if(!sharedAudioCtx){
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if(!Ctx) return null;
    sharedAudioCtx = new Ctx();
  }
  if(sharedAudioCtx.state === "suspended") sharedAudioCtx.resume();
  return sharedAudioCtx;
}

// Tavarakohtaiset erikoisäänet. Lisää tähän uusia rivejä samalla tavalla.
// Käyttäjän omat, rojaltivapaat äänitiedostot tietyille tavaroille.
const AUDIO_CLIPS = {
  running: "data:audio/mpeg;base64,",
  glug: "data:audio/mpeg;base64,",
  puddle: "data:audio/mpeg;base64,",
  yay: "data:audio/mpeg;base64,",
  yopuku: "data:audio/mpeg;base64,",
  hammasharja: "data:audio/mpeg;base64,",
  puhelin: "data:audio/mpeg;base64,",
  unilelu: "data:audio/mpeg;base64,",
  pyyhe: "data:audio/mpeg;base64,"
};

const ITEM_SOUND = {
  "Yöpuku": "audio:yopuku",
  "Lenkkarit": "audio:running",
  "Kumisaappaat": "audio:puddle",
  "Nimikoitu vesipullo": "audio:glug",
  "Nimikoitu pussi, jossa hammasharja ja -muki": "audio:hammasharja",
  "Puhelin nimellä, hälytykset ja herätykset pois": "audio:puhelin",
  "Unilelu": "audio:unilelu",
  "Pyyhe": "audio:pyyhe"
};

function playItemSound(label){
  const type = ITEM_SOUND[label] || "creak";
  if(type === "sigh") playSighSound();
  else if(type.indexOf("audio:") === 0) playAudioClip(type.slice(6));
  else playCreakSound();
}

function playAudioClip(key){
  try{
    const src = AUDIO_CLIPS[key];
    if(!src) return;
    const audio = new Audio(src);
    audio.play().catch(()=>{ /* selain esti automaattisen toiston, ei kriittistä */ });
  }catch(e){ /* äänet eivät ole pakollisia toiminnalle */ }
}

function playSighSound(){
  try{
    const ctx = getAudioCtx();
    if(!ctx) return;
    const now = ctx.currentTime;
    const duration = 0.75;

    // Selkeä, kuuluva sävelosuus: laskeva "aah", kuuluu varmasti pienestäkin kaiuttimesta
    const tone = ctx.createOscillator();
    const toneGain = ctx.createGain();
    tone.type = "triangle";
    tone.frequency.setValueAtTime(480, now);
    tone.frequency.exponentialRampToValueAtTime(190, now + duration);
    toneGain.gain.setValueAtTime(0.0001, now);
    toneGain.gain.exponentialRampToValueAtTime(0.5, now + 0.08);
    toneGain.gain.exponentialRampToValueAtTime(0.35, now + 0.35);
    toneGain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    tone.connect(toneGain);
    toneGain.connect(ctx.destination);
    tone.start(now);
    tone.stop(now + duration);

    // Kohina päälle tuomaan hengitysmäistä sävyä sävelen rinnalle
    const bufferSize = Math.floor(ctx.sampleRate * duration);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for(let i = 0; i < bufferSize; i++){
      data[i] = (Math.random() * 2 - 1) * (1 - i / bufferSize);
    }
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const formant = ctx.createBiquadFilter();
    formant.type = "bandpass";
    formant.Q.value = 0.9;
    formant.frequency.setValueAtTime(1200, now);
    formant.frequency.exponentialRampToValueAtTime(320, now + duration);
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.0001, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.28, now + 0.1);
    noiseGain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    noise.connect(formant);
    formant.connect(noiseGain);
    noiseGain.connect(ctx.destination);
    noise.start(now);
    noise.stop(now + duration);
  }catch(e){ /* äänet eivät ole pakollisia toiminnalle */ }
}

// Matkalaukun lukon narahdus + pieni naksahdus kiinni mennessä
function playCreakSound(){
  try{
    const ctx = getAudioCtx();
    if(!ctx) return;
    const now = ctx.currentTime;

    // Narahdus: korkeampi ja vinkuvampi, kapea kaistanpäästösuodatin korostaa sirinää
    const creakOsc = ctx.createOscillator();
    const creakFilter = ctx.createBiquadFilter();
    const creakGain = ctx.createGain();
    creakOsc.type = "sawtooth";
    creakFilter.type = "bandpass";
    creakFilter.frequency.setValueAtTime(1300, now);
    creakFilter.Q.value = 14;
    const curve = new Float32Array([1500, 1150, 1400, 950, 1250, 800, 1000, 650]);
    creakOsc.frequency.setValueCurveAtTime(curve, now, 0.22);
    creakGain.gain.setValueAtTime(0.0001, now);
    creakGain.gain.exponentialRampToValueAtTime(0.3, now + 0.03);
    creakGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.23);
    creakOsc.connect(creakFilter);
    creakFilter.connect(creakGain);
    creakGain.connect(ctx.destination);
    creakOsc.start(now);
    creakOsc.stop(now + 0.24);

    // Naksahdus: kuuluvampi, matala tömähdys yhdistettynä lyhyeen napsahduspiikkiin
    const clickTime = now + 0.2;
    const clickOsc = ctx.createOscillator();
    const clickGain = ctx.createGain();
    clickOsc.type = "sine";
    clickOsc.frequency.setValueAtTime(200, clickTime);
    clickOsc.frequency.exponentialRampToValueAtTime(55, clickTime + 0.14);
    clickGain.gain.setValueAtTime(0.0001, clickTime);
    clickGain.gain.exponentialRampToValueAtTime(0.85, clickTime + 0.012);
    clickGain.gain.exponentialRampToValueAtTime(0.0001, clickTime + 0.2);
    clickOsc.connect(clickGain);
    clickGain.connect(ctx.destination);
    clickOsc.start(clickTime);
    clickOsc.stop(clickTime + 0.2);

    // Lyhyt kohinapiikki tekee naksahduksesta terävämmän ja kuuluvamman
    const snapBufferSize = Math.floor(ctx.sampleRate * 0.03);
    const snapBuffer = ctx.createBuffer(1, snapBufferSize, ctx.sampleRate);
    const snapData = snapBuffer.getChannelData(0);
    for(let i = 0; i < snapBufferSize; i++){
      snapData[i] = (Math.random() * 2 - 1) * (1 - i / snapBufferSize);
    }
    const snap = ctx.createBufferSource();
    snap.buffer = snapBuffer;
    const snapFilter = ctx.createBiquadFilter();
    snapFilter.type = "highpass";
    snapFilter.frequency.value = 1200;
    const snapGain = ctx.createGain();
    snapGain.gain.setValueAtTime(0.5, clickTime);
    snapGain.gain.exponentialRampToValueAtTime(0.0001, clickTime + 0.03);
    snap.connect(snapFilter);
    snapFilter.connect(snapGain);
    snapGain.connect(ctx.destination);
    snap.start(clickTime);
  }catch(e){ /* äänet eivät ole pakollisia toiminnalle */ }
}

function packAnimation(icon){
  const flyingBig = document.getElementById("flyingIconBig");

  // Tavaran oma kuvake hyppää laukkuun ja häivytetään pikkuhiljaa lennon aikana
  if(flyingBig){
    flyingBig.textContent = icon;
    flyingBig.classList.remove("fly");
    void flyingBig.offsetWidth; // pakotettu reflow, jotta animaatio toistuu
    flyingBig.classList.add("fly");
  }

  if(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches){
    return;
  }

  clearTimeout(packTimer1);
  // Laukku sulkeutuu tavaran perään ja aukeaa taas, hieman hidastettuna
  const closing = [1,2,3,4,5,6,7];
  const opening = [6,5,4,3,2,1,0];
  playFrames(closing, 122, ()=>{
    // Laukku on juuri sulkeutunut: pieni tärähdys
    const bigImg = document.getElementById("suitcaseImgBig");
    if(bigImg){
      bigImg.classList.remove("suitcase-jolt");
      void bigImg.offsetWidth;
      bigImg.classList.add("suitcase-jolt");
    }
    packTimer1 = setTimeout(()=>{
      playFrames(opening, 60, null);
    }, 260);
  });
}

function dropLeaves(){
  if(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const emojis = ["🍁","🍂","🍃"];
  for(let i=0;i<18;i++){
    const leaf = document.createElement("span");
    leaf.className = "leaf";
    leaf.textContent = emojis[Math.floor(Math.random()*emojis.length)];
    leaf.style.left = Math.random()*100 + "vw";
    leaf.style.animationDuration = (2.5 + Math.random()*2) + "s";
    document.body.appendChild(leaf);
    setTimeout(()=>leaf.remove(), 5000);
  }
}

document.getElementById("resetBtn").addEventListener("click", ()=>{
  state = {};
  saveState();
  renderChecklist();
  renderProgress();
  document.getElementById("celebrateBox").classList.remove("show");
  document.getElementById("readyFeedback").textContent = "";
});

document.getElementById("readyBtn").addEventListener("click", checkReady);

renderChecklist();
renderProgress();
